<?php
declare(strict_types=1);
namespace Sabri\CentralMedia;
final class WorkspaceUploadService {
    public static function authorize(string $type,array $in,int $actor): array { $ctx=self::normalizeContext($type,$in); if($ctx['native_owner']===''||$ctx['native_object_id']==='') throw new Error('workspace_owner_context_required','Native workspace owner and object are required.',400); Auth::domainDecision($ctx['native_owner'],'authorize_upload',['actor_id'=>$actor,'workspace'=>$ctx]); return $ctx; }
    public static function normalizeContext(string $type,array $in): array { $type=Utils::key($type,16); if(!in_array($type,['image','audio'],true)) throw new Error('workspace_media_type_invalid','Unsupported workspace media type.',400); $base=['type'=>$type,'source'=>Utils::key((string)($in['source']??'upload'),32),'title'=>Utils::text((string)($in['title']??''),160),'caption'=>Utils::text((string)($in['caption']??''),1000),'native_owner'=>Utils::key((string)($in['native_owner']??''),64),'native_object_id'=>Utils::text((string)($in['native_object_id']??''),191),'strip_location_metadata'=>true]; if($type==='image'){ $rot=(int)($in['rotation_degrees']??0); if(!in_array($rot,[0,90,180,270],true)) throw new Error('image_rotation_invalid','Image rotation must be 0, 90, 180 or 270.',400); $q=(int)($in['compression_quality']??82); if($q<40||$q>95) throw new Error('image_compression_quality_invalid','Image compression quality is outside policy.',400); $base+=['rotation_degrees'=>$rot,'compression_quality'=>$q,'alt_text'=>Utils::text((string)($in['alt_text']??''),400),'crop_requested'=>Utils::bool($in['crop_requested']??false)]; if($base['crop_requested']){ $crop=['x'=>(int)($in['crop_x']??0),'y'=>(int)($in['crop_y']??0),'width'=>(int)($in['crop_width']??0),'height'=>(int)($in['crop_height']??0)]; if($crop['x']<0||$crop['y']<0||$crop['width']<1||$crop['height']<1) throw new Error('image_crop_invalid','Invalid crop rectangle.',400); $base['crop']=$crop; } } else { $base+=['waveform_required'=>true,'transcript_requested'=>Utils::bool($in['transcript_requested']??false),'captions_requested'=>Utils::bool($in['captions_requested']??false),'language'=>Utils::key((string)($in['language']??'und'),16)]; } return $base; }
